// device-web-ui kit v3: ESP32 (Arduino WebServer) side of the standard page.
// The same conventions as the EBC-A20 bridge and PocketCW firmware.
#pragma once
#include <WebServer.h>
#include <WiFi.h>

namespace webkit {

// Serves the gzipped page generated by embed_ui.py (web_page.h).
inline void sendPage(WebServer& s, const uint8_t* gz, size_t len) {
  s.sendHeader("Content-Encoding", "gzip");
  s.sendHeader("Cache-Control", "no-cache");
  s.send_P(200, "text/html", (const char*)gz, len);
}

// Every request that changes something: HTTP Basic login, user "admin". An empty password means no login
// (first setup); projects keep the password in a gitignored secret file or in their settings.
inline bool requireAuth(WebServer& s, const char* password, const char* realm) {
  if (!password || !*password) return true;
  if (s.authenticate("admin", password)) return true;
  s.requestAuthentication(BASIC_AUTH, realm, "Login required to change settings");
  return false;
}

inline String htmlEscape(const String& in) {
  String o;
  o.reserve(in.length() + 8);
  for (char c : in) {
    switch (c) {
      case '&': o += "&amp;"; break;
      case '<': o += "&lt;"; break;
      case '>': o += "&gt;"; break;
      case '"': o += "&quot;"; break;
      case '\'': o += "&#39;"; break;
      default: o += c;
    }
  }
  return o;
}

// Reply to a plain form POST: a short message, then back to the page.
inline void backHome(WebServer& s, const String& msg, int seconds = 3) {
  s.send(200, "text/html",
         "<!doctype html><meta name=viewport content='width=device-width'><meta http-equiv=refresh content='" + String(seconds) +
             ";url=/'><body style='font-family:system-ui;padding:16px'>" + htmlEscape(msg) + "<p><a href='/'>Back</a></p>");
}

inline String jsonEscape(const String& in) {
  String e;
  for (char c : in) {
    if (c == '"' || c == '\\') e += '\\';
    if ((uint8_t)c >= 0x20) e += c;
  }
  return e;
}

// GET /wifi/scan?start=1 starts an async scan; GET /wifi/scan returns
// {"running":bool,"list":[{"ssid","rssi","ch","open"}],"current":"<saved ssid>"} (strongest first, duplicates merged).
inline void wifiScan(WebServer& s, const String& current) {
  if (s.hasArg("start")) {
    if (WiFi.scanComplete() != WIFI_SCAN_RUNNING) {
      WiFi.scanDelete();
      WiFi.scanNetworks(true);
    }
    s.send(200, "application/json", "{\"running\":true}");
    return;
  }
  int n = WiFi.scanComplete();
  if (n == WIFI_SCAN_RUNNING) return s.send(200, "application/json", "{\"running\":true}");
  if (n < 0) return s.send(200, "application/json", "{\"running\":false}");
  String j = "{\"running\":false,\"current\":\"" + jsonEscape(current) + "\",\"list\":[";
  bool first = true;
  for (int i = 0; i < n; i++) {
    String ssid = WiFi.SSID(i);
    if (!ssid.length()) continue;
    // Keep one entry per SSID: the strongest (earliest on a tie), wherever it sits in the scan results.
    bool dup = false;
    for (int k = 0; k < n && !dup; k++) {
      if (k == i || WiFi.SSID(k) != ssid) continue;
      dup = WiFi.RSSI(k) > WiFi.RSSI(i) || (WiFi.RSSI(k) == WiFi.RSSI(i) && k < i);
    }
    if (dup) continue;
    j += String(first ? "" : ",") + "{\"ssid\":\"" + jsonEscape(ssid) + "\",\"rssi\":" + WiFi.RSSI(i) + ",\"ch\":" + WiFi.channel(i) +
         ",\"open\":" + (WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? "true" : "false") + "}";
    first = false;
  }
  s.send(200, "application/json", j + "]}");
}

}  // namespace webkit
